const ensureExtendedState=()=>{for(const key of ['donors','screenings','labOrders'])if(!state[key])state[key]=structuredClone(seed[key])};
let state=JSON.parse(localStorage.getItem('lifeflow-demo')||'null')||structuredClone(seed);const save=()=>localStorage.setItem('lifeflow-demo',JSON.stringify(state));const api=async(path,options={})=>{const response=await fetch(path,{headers:{'Content-Type':'application/json'},...options});if(!response.ok)throw new Error(`API ${response.status}`);return response.json()};const persist=async(path,payload)=>{try{await api(path,{method:'POST',body:JSON.stringify(payload)});state=await api('/api/state');save();return true}catch{return false}};const view=document.querySelector('#view'),toast=document.querySelector('#toast');const counts={'O+':48,'O-':8,'A+':37,'A-':14,'B+':26,'B-':11,'AB+':18,'AB-':5},levels={'O+':82,'O-':22,'A+':70,'A-':42,'B+':58,'B-':35,'AB+':52,'AB-':17};
const cls=s=>String(s).toLowerCase().replaceAll(' ','-'),notify=m=>{toast.textContent=m;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2500)},shell=(t,k,a='')=>`<div class="page-head"><div><span class="eyebrow">${k}</span><h2>${t}</h2></div>${a}</div>`,table=(h,r)=>`<div class="table-wrap"><table><thead><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${r.join('')}</tbody></table></div>`,types=()=>Object.keys(compatibility).map(x=>`<option>${x}</option>`).join('');
const he=new Map(Object.entries({'Live operations':'תפעול בזמן אמת','Every unit accounted for.':'כל Blood Unit מנוהלת ומתועדת.','Monitor inventory, protect rare blood types, and move every approved unit to the right patient—safely and on time.':'ניהול מלאי, הגנה על Blood Types נדירים והעברת כל Blood Unit מאושרת למטופל המתאים בבטיחות ובזמן.','View inventory':'צפייה במלאי','Available units':'Blood Units זמינות','Open requests':'בקשות פתוחות','Donations today':'תרומות היום','Expiring soon':'תוקף מסתיים בקרוב','Inventory by blood type':'מלאי לפי Blood Type','See all':'הצגת הכול','Recent activity':'פעילות אחרונה','Predictive alert':'התראת חיזוי','Expiry protection':'מניעת פקיעת תוקף','Schedule a targeted campaign for 18 eligible donors.':'מומלץ לפתוח קמפיין ממוקד עבור 18 תורמים מתאימים.','Review forecast':'בדיקת התחזית','Find requests':'איתור בקשות','Blood inventory':'מלאי Blood Units','Operations':'תפעול','Scan QR':'סריקת QR','All statuses':'כל הסטטוסים','Export':'ייצוא','Type':'Blood Type','Branch':'סניף','Expires':'תאריך תפוגה','Status':'סטטוס','Details':'פרטים','Blood requests':'בקשות דם','Hospital coordination':'תיאום בתי חולים','New request':'בקשה חדשה','Open':'פתוחות','Urgent':'דחופות','Request':'בקשה','Patient':'מטופל','Hospital':'בית חולים','Units':'Blood Units','Urgency':'דחיפות','Find match':'Smart Match','Donations':'תרומות','Donor intake':'קליטת תורמים','Register donation':'רישום תרומה','Donor':'תורם','Collection':'איסוף','Testing':'בדיקות','Approval':'אישור','Date':'תאריך','Next appointments':'התורים הבאים','First donation':'תרומה ראשונה','Returning donor':'תורם חוזר','Compatibility checker':'בדיקת Compatibility','Clinical decision support':'Clinical Decision Support','Donor blood type':'Blood Type של התורם','Recipient blood type':'Blood Type של המקבל','Check compatibility':'בדיקת Compatibility','Select blood types':'בחרו Blood Types','The result and reasoning will appear here.':'התוצאה וההסבר יוצגו כאן.','Mass casualty protocol':'פרוטוקול אירוע רב נפגעים','Emergency command center':'מרכז שליטה לשעת חירום','Activate emergency mode':'הפעלת Emergency Mode','Critical requests':'בקשות קריטיות','Immediate units':'Blood Units זמינות מיידית','Hospitals connected':'בתי חולים מחוברים','Allocation board':'לוח הקצאה','Priority':'עדיפות','Need':'נדרש','Recommendation':'המלצה','Decision timeline':'ציר החלטות','Shortage & expiry forecast':'חיזוי מחסור ותפוגה','Predictive inventory':'Predictive Inventory','7-day risk':'סיכון ב 7 ימים','Action required':'נדרשת פעולה','Planned donations':'תרומות מתוכננות','30-day projection':'תחזית ל 30 ימים','Recommended action':'פעולה מומלצת','Administration':'ניהול מערכת','Security & compliance':'אבטחה ו Compliance','Export audit trail':'ייצוא Audit Trail','Users':'משתמשים','Roles':'הרשאות','System health':'מצב מערכת','Time':'שעה','User':'משתמש','Action':'פעולה','Record':'רשומה','Result':'תוצאה','Recorded':'תועד','Part 11 controls':'בקרות Part 11','Privacy safeguards':'הגנת פרטיות','New blood request':'בקשת דם חדשה','Patient record':'מספר תיק מטופל','Save request':'שמירת בקשה','Donor name':'שם התורם','Age':'גיל','Weight kg':'משקל בקילוגרמים','Days since last donation':'ימים מאז התרומה האחרונה','Check and register':'בדיקה ורישום','Smart matching':'Smart Matching','Ranked by compatibility, expiry, location, and rare-type protection.':'דירוג לפי Compatibility, תוקף, מיקום והגנה על Blood Types נדירים.','Reserve':'שמירה','QR unit profile':'פרופיל QR של Blood Unit','Location':'מיקום','Chain of custody':'Chain of Custody'}));
function localize(root=document){const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){const raw=n.nodeValue,trim=raw.trim();if(he.has(trim))n.nodeValue=raw.replace(trim,he.get(trim));else for(const[a,b]of he)if(trim.includes(a)&&a.length>10)n.nodeValue=raw.replace(a,b)}}
new MutationObserver(m=>m.forEach(x=>x.addedNodes.forEach(n=>{if(n.nodeType===1)localize(n)}))).observe(document.body,{childList:true,subtree:true});
const bloodCards=()=>Object.entries(counts).map(([t,c])=>`<div class="blood-card ${c<10?'critical':c<15?'warning':''}"><strong>${t}</strong><span>${c} units available</span><div class="bar"><i style="width:${levels[t]}%"></i></div></div>`).join('');
function dashboard(){return`<div class="hero-strip"><div><span class="eyebrow">Live operations</span><h2>Every unit accounted for.</h2><p>Monitor inventory, protect rare blood types, and move every approved unit to the right patient—safely and on time.</p><button class="ghost" data-route="inventory">View inventory</button></div><div class="hero-visual"><div class="pulse">♥</div></div></div><div class="metric-grid"><div class="card metric"><small>Available units</small><strong>167</strong><span class="trend">↑ 8.4% this week</span></div><div class="card metric"><small>Open requests</small><strong>${state.requests.filter(x=>x.status==='Open').length}</strong><span class="trend">1 requires attention</span></div><div class="card metric"><small>Donations today</small><strong>31</strong><span class="trend">22 approved</span></div><div class="card metric"><small>Expiring soon</small><strong>9</strong><span class="trend">Within 7 days</span></div></div><div class="section-grid"><div class="card"><div class="section-title"><h2>Inventory by blood type</h2><button class="ghost" data-route="inventory">See all</button></div><div class="blood-grid">${bloodCards()}</div></div><div class="card"><div class="section-title"><h2>Recent activity</h2></div><div class="activity">${state.audit.slice(0,4).map(a=>`<div class="activity-item"><i class="dot"></i><div><p>${a.action}</p><small>${a.time} · ${a.user} · ${a.record}</small></div></div>`).join('')}</div></div></div><div class="insight-row"><div class="card insight"><span>Predictive alert</span><h3>O- may fall below safety stock in 6 days</h3><p>Schedule a targeted campaign for 18 eligible donors.</p><button class="ghost" data-route="analytics">Review forecast</button></div><div class="card insight"><span>Expiry protection</span><h3>3 units should be allocated first</h3><p>Smart matching prioritizes approved units approaching expiry.</p><button class="ghost" data-route="requests">Find requests</button></div></div>`}
function inventory(){return shell('Blood inventory','Operations','<button class="primary" data-action="scan">Scan QR</button>')+`<div class="blood-grid compact">${bloodCards()}</div><div class="card filters"><input id="inventorySearch" placeholder="Search unit ID, branch or component"><select id="statusFilter"><option value="All statuses">All statuses</option><option value="Available">Available</option><option value="Reserved">Reserved</option><option value="Pending Testing">Pending Testing</option></select></div><div class="card"><p id="inventoryCount" class="filter-count">${state.inventory.length} Blood Units</p>${table(['Unit ID','Type','Component','Branch','Expires','Status',''],state.inventory.map(u=>`<tr class="inventory-row" data-search="${[u.id,u.type,u.component,u.branch].join(' ').toLowerCase()}" data-status="${u.status}"><td><strong>${u.id}</strong></td><td><span class="blood-pill">${u.type}</span></td><td>${u.component}</td><td>${u.branch}</td><td>${u.expires}</td><td><span class="badge ${cls(u.status)}">${u.status}</span></td><td><button class="link-btn" data-unit="${u.id}">Details</button></td></tr>`))}<div id="inventoryEmpty" class="empty-state" hidden>No Blood Units match this filter.</div></div>`}
function requests(){return shell('Blood requests','Hospital coordination','<button class="primary" data-modal="request">+ New request</button>')+`<div class="stats-line"><div class="mini-stat"><strong>12</strong><span>Open</span></div><div class="mini-stat"><strong>4</strong><span>Urgent</span></div><div class="mini-stat"><strong>96%</strong><span>Matched on time</span></div></div><div class="card">${table(['Request','Patient','Hospital','Type','Units','Urgency','Status',''],state.requests.map(r=>`<tr><td><strong>${r.id}</strong></td><td>${r.patient}</td><td>${r.hospital}</td><td><span class="blood-pill">${r.type}</span></td><td>${r.units}</td><td><span class="badge ${cls(r.urgency)}">${r.urgency}</span></td><td>${r.status}</td><td><button class="link-btn" data-match="${r.id}">Find match</button></td></tr>`))}</div>`}
function donations(){return shell('תרומות','קליטת תורמים','<button class="primary" data-modal="donation">+ רישום תרומה</button>')+`<div class="step-strip" aria-label="שלבי תהליך התרומה"><button data-donation-step="donor"><b>1</b> תיק תורם</button><button data-donation-step="eligibility"><b>2</b> בדיקת Eligibility</button><button data-donation-step="collection"><b>3</b> איסוף Blood Unit</button><button data-donation-step="testing"><b>4</b> בדיקות מעבדה</button><button data-donation-step="approval"><b>5</b> אישור למלאי</button></div><div id="donationStepInfo" class="feature-note"><b>תהליך תרומה מלא</b><span>בחרו שלב כדי לפתוח את הפעולה או להציג את הרשומות המתאימות.</span></div><div class="section-grid"><div class="card">${table(['Donation','Donor','Type','Date','Status'],state.donations.map(d=>`<tr class="donation-row" data-status="${d.status}"><td><strong>${d.id}</strong></td><td>${d.donor}</td><td><span class="blood-pill">${d.type}</span></td><td>${d.date}</td><td><span class="badge ${cls(d.status)}">${d.status}</span></td></tr>`))}</div><div class="card"><div class="section-title"><h2>התורים הבאים</h2></div>${['10:30 · Lina Mansour|O- · תרומה ראשונה','11:15 · Daniel Azulay|A+ · תורם חוזר','12:00 · Noor Abu Ali|B+ · תורם חוזר'].map(x=>{let[a,b]=x.split('|');return`<div class="appointment"><strong>${a}</strong><span>${b}</span></div>`}).join('')}</div></div>`}
function compatibilityPage(){return shell('Compatibility checker','Clinical decision support')+`<div class="form-layout"><form id="compatForm" class="card form-card"><label>Donor blood type<select name="donor">${types()}</select></label><label>Recipient blood type<select name="recipient">${types()}</select></label><label>Component<select><option>Red blood cells</option><option>Plasma</option><option>Platelets</option></select></label><button class="primary">Check compatibility</button></form><div id="compatResult" class="card result-card"><div class="result-icon">?</div><h3>Select blood types</h3><p>The result and reasoning will appear here.</p></div></div><p class="clinical-note">Educational decision support only. Final transfusion decisions require qualified staff, laboratory testing, and the institution's approved protocol.</p>`}
function emergency(){return`<div class="emergency-head"><div><span class="eyebrow">Mass casualty protocol</span><h2>Emergency command center</h2><p>Coordinated allocation with double-booking protection and a complete decision trail.</p></div><button class="danger" data-action="emergency">Activate emergency mode</button></div><div class="metric-grid"><div class="card metric"><small>Critical requests</small><strong>7</strong><span class="red-text">3 unmatched</span></div><div class="card metric"><small>Immediate units</small><strong>112</strong><span>Across 3 centers</span></div><div class="card metric"><small>O- available</small><strong>8</strong><span class="red-text">Critical level</span></div><div class="card metric"><small>Hospitals connected</small><strong>3</strong><span>All online</span></div></div><div class="section-grid"><div class="card"><div class="section-title"><h2>Allocation board</h2><span class="badge critical">Live priority</span></div>${table(['Priority','Hospital','Need','Recommendation'],['<tr><td>P1</td><td>Soroka ER</td><td>3 × O-</td><td>LF-2049 + 2 nearby</td></tr>','<tr><td>P1</td><td>Barzilai Trauma</td><td>2 × A+</td><td>2 exact matches</td></tr>','<tr><td>P2</td><td>Assuta Ashdod</td><td>2 × B+</td><td>1 exact + 1 compatible</td></tr>'])}</div><div class="card"><div class="section-title"><h2>Decision timeline</h2></div><div class="activity"><div class="activity-item"><i class="dot red-dot"></i><div><p>Protocol ready</p><small>Awaiting manager activation</small></div></div><div class="activity-item"><i class="dot"></i><div><p>All centers synchronized</p><small>Inventory refreshed 1 min ago</small></div></div><div class="activity-item"><i class="dot"></i><div><p>No allocation conflicts</p><small>Automatic safety check</small></div></div></div></div></div>`}
function analytics(){return shell('Shortage & expiry forecast','Predictive inventory')+`<div class="metric-grid"><div class="card metric"><small>7-day risk</small><strong>O-</strong><span class="red-text">Action required</span></div><div class="card metric"><small>Expiring in 7 days</small><strong>9</strong><span>3 high priority</span></div><div class="card metric"><small>Planned donations</small><strong>46</strong><span>Next 14 days</span></div><div class="card metric"><small>Preventable waste</small><strong>73%</strong><span>With FEFO matching</span></div></div><div class="card"><div class="section-title"><h2>30-day projection</h2><button class="ghost" data-action="campaign">Create O- campaign</button></div><div class="forecast-chart">${Object.keys(counts).map((t,i)=>{let v=forecast(counts[t],i%3+1,i%2?8:14,30);return`<div class="forecast-col"><span>${v}</span><i style="height:${Math.max(12,v*2)}px" class="${v<10?'low':''}"></i><b>${t}</b></div>`}).join('')}</div></div><div class="card recommendation"><strong>Recommended action</strong><p>Contact 18 eligible O- donors within 7 days and reserve rare units for exact-match or emergency use.</p></div>`}
function admin(){const panels={audit:table(['Time','User','Action','Record','Result'],state.audit.map(a=>`<tr><td>${a.time}</td><td>${a.user}</td><td>${a.action}</td><td>${a.record}</td><td><span class="badge available">Recorded</span></td></tr>`)),users:'<h3>משתמשים פעילים</h3><p>Noa Adler · Blood Bank staff<br>Dr. Samir Haddad · Hospital<br>Dana Levy · Donor</p>',roles:'<h3>Role-based access</h3><p>Admin: full audit access · Staff: inventory and matching · Hospital: requests · Donor: donation intake.</p>',health:'<h3>System health</h3><p><span class="badge available">Online</span> API, SQLite database, audit log and inventory services are operational.</p>'};return shell('Administration','Security & compliance')+`<div class="tab-row"><button class="tab active" data-admin-tab="audit">Audit trail</button><button class="tab" data-admin-tab="users">Users</button><button class="tab" data-admin-tab="roles">Roles</button><button class="tab" data-admin-tab="health">System health</button></div><div id="adminPanel" class="card" data-panels='${JSON.stringify(panels).replaceAll("'","&#39;")}'>${panels.audit}</div><div class="compliance-grid"><div class="card"><h3>Part 11 controls</h3><ul class="check-list"><li>Immutable audit entries</li><li>Authorized approvals</li><li>Timestamped changes</li><li>Exportable history</li></ul></div><div class="card"><h3>Privacy safeguards</h3><ul class="check-list"><li>Role-based access</li><li>Minimum necessary display</li><li>Research data anonymization</li><li>Session logging</li></ul></div></div>`}
dashboard=()=>`<section class="command-hero"><div class="command-copy"><span class="live-signal"><i></i> המערכת מסונכרנת בזמן אמת</span><h2>Blood Operations<br><em>Command Center</em></h2><p>תמונה אחת שמחברת בין Blood Units, בתי חולים ותורמים ומאפשרת לצוות לקבל החלטות בטוחות במהירות.</p><div class="command-actions"><button class="primary" data-route="requests">פתיחת בקשת דם</button><button class="ghost" data-route="inventory">בדיקת מלאי</button></div></div><div class="network-map"><svg viewBox="0 0 420 300" aria-hidden="true"><path d="M210 150 L80 66 M210 150 L340 62 M210 150 L342 235"/><circle cx="210" cy="150" r="76"/></svg><div class="hub">LF<span>167 Blood Units</span></div><div class="map-node node-a">Soroka<b>72</b></div><div class="map-node node-b">Barzilai<b>51</b></div><div class="map-node node-c">Assuta<b>44</b></div></div></section><section class="ops-ribbon"><article><span>01</span><div><b>O- מתחת ל Safety Stock</b><small>Shortage Prediction · נדרשת פעולה בתוך 6 ימים</small></div></article><article><span>02</span><div><b>3 Blood Units בעדיפות</b><small>Expiry Radar · הקצאה לפי FEFO</small></div></article><article><span>03</span><div><b>${state.requests.filter(x=>x.status==='Open').length} בקשות פתוחות</b><small>Explainable Smart Matching מוכן</small></div></article><article><span>04</span><div><b>31 תרומות היום</b><small>Donor Eligibility נבדק לפני קליטה</small></div></article></section><section class="command-grid"><div class="mission-panel"><header><span>LIVE INVENTORY PULSE</span><button data-route="analytics">Forecasting ←</button></header><div class="blood-wave">${Object.entries(counts).map(([t,c])=>`<div><b>${t}</b><i style="height:${Math.max(18,levels[t])}%" class="${c<10?'risk':''}"></i><span>${c}</span></div>`).join('')}</div></div><div class="decision-feed"><header><span>DECISION FEED</span><button data-route="admin">Audit Trail ←</button></header>${state.audit.slice(0,4).map((a,i)=>`<article><time>${a.time}</time><div><b>${a.action}</b><small>${a.record} · ${a.user}</small></div><span>0${i+1}</span></article>`).join('')}</div></section><section class="quick-lanes"><button data-route="compatibility"><span>Compatibility</span><b>בדיקת התאמה</b><small>Decision Support מוסבר</small></button><button data-route="emergency"><span>Emergency Simulator</span><b>תרחיש רב נפגעים</b><small>בדיקה לפני הפעלת הפרוטוקול</small></button><button data-route="inventory"><span>Digital Passport</span><b>מעקב QR</b><small>Chain of Custody לכל Blood Unit</small></button></section>`;
function donors(){return shell('תיקי תורמים','Donor Medical Records','<button class="primary" data-modal="donation">+ קליטת תורם ותרומה</button>')+`<div class="feature-note"><b>Donor Eligibility Assessment</b><span>המערכת בודקת גיל, משקל, מרווח מתרומה קודמת ומצב רפואי לפני הקליטה.</span></div><div class="card">${table(['מספר תורם','שם','Blood Type','טלפון','מצב רפואי','תרומה אחרונה',''],state.donors.map(d=>`<tr><td><strong>${d.id}</strong></td><td>${d.name}</td><td><span class="blood-pill">${d.type}</span></td><td>${d.phone}</td><td>${d.conditions}</td><td>${d.lastDonation}</td><td><button class="link-btn" data-donor="${d.id}">פתיחת תיק</button></td></tr>`))}</div>`}
function screening(){return shell('בדיקות מנות דם','Infectious Disease Screening')+`<div class="feature-note"><b>Automated Safety Release</b><span>Blood Unit נשארת ב־Pending Testing ולא זמינה לשימוש עד שכל הבדיקות שליליות.</span></div><div class="card">${table(['Screening','Donation','Blood Unit','HIV','HBV','HCV','Syphilis','תוצאה',''],state.screenings.map(s=>`<tr><td><strong>${s.id}</strong></td><td>${s.donationId}</td><td>${s.unitId}</td><td>${s.hiv}</td><td>${s.hbv}</td><td>${s.hcv}</td><td>${s.syphilis}</td><td><span class="badge ${cls(s.result)}">${s.result}</span></td><td>${s.result==='Pending'?`<button class="primary small" data-screen="${s.id}">הזנת תוצאות</button>`:'נבדק '+s.testedAt}</td></tr>`))}</div>`}
function labOrders(){return shell('בדיקות דם למטופלים','Patient Laboratory','<button class="primary" data-modal="lab">+ הזמנת בדיקה</button>')+`<div class="feature-note"><b>Symptom-to-Test Assistant</b><span>הרופא מתאר תסמינים, בוחר בדיקות מתאימות ועוקב אחרי סטטוס התוצאה.</span></div><div class="card">${table(['הזמנה','מטופל','תיק','תסמינים','סוג בדיקה','רופא','סטטוס'],state.labOrders.map(o=>`<tr><td><strong>${o.id}</strong></td><td>${o.patient}</td><td>${o.patientCode}</td><td>${o.symptoms}</td><td>${o.testType}</td><td>${o.doctor}</td><td><span class="badge ${cls(o.status)}">${o.status}</span></td></tr>`))}</div>`}
const pages={dashboard,inventory,requests,donations,donors,screening,'lab-orders':labOrders,compatibility:compatibilityPage,emergency,analytics,admin};
function modal(kind){let h;if(kind==='request')h=`<h2>בקשת Blood Units</h2><form id="requestForm" class="modal-form"><label>מספר תיק<input name="patient" required placeholder="PT-00000"></label><label>בית חולים<select name="hospital"><option>Soroka</option><option>Barzilai</option><option>Assuta Ashdod</option></select></label><label>Blood Type<select name="type">${types()}</select></label><label>כמות Blood Units<input name="units" type="number" min="1" max="10" value="1"></label><label>דחיפות<select name="urgency"><option>Routine</option><option>Urgent</option><option>Critical</option></select></label><button class="primary">שמירת בקשה</button></form>`;else if(kind==='lab')h=`<h2>הזמנת בדיקת דם למטופל</h2><form id="labForm" class="modal-form"><label>שם המטופל<input name="patient" required></label><label>מספר תיק<input name="patientCode" required placeholder="PT-00000"></label><label>תסמינים וסיבת הבדיקה<textarea name="symptoms" required placeholder="לדוגמה: עייפות, סחרחורת ותחושת חולשה"></textarea></label><label>בדיקות נדרשות<select name="testType"><option>CBC + Ferritin</option><option>Glucose + HbA1c</option><option>Thyroid Panel (TSH, T4)</option><option>Liver Function Tests</option><option>Vitamin B12 + Folate</option><option>Lipid Profile</option></select></label><label>רופא מפנה<input name="doctor" required value="Dr. Haddad"></label><button class="primary">שליחת הזמנה למעבדה</button></form>`;else h=`<h2>קליטת תורם ותרומה</h2><form id="donationForm" class="modal-form"><label>שם התורם<input name="donor" required></label><label>טלפון<input name="phone" required placeholder="050-0000000"></label><label>Blood Type<select name="type">${types()}</select></label><label>גיל<input name="age" type="number" min="18" value="30"></label><label>משקל בק״ג<input name="weight" type="number" min="45" value="70"></label><label>ימים מאז התרומה האחרונה<input name="days" type="number" min="0" value="90"></label><label>מחלות, תרופות או מגבלות<textarea name="conditions" placeholder="None reported"></textarea></label><button class="primary">בדיקת Eligibility וקליטת התרומה</button></form>`;document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop"><div class="modal"><button class="modal-close">×</button>${h}</div></div>`)}
function donorFile(id){const d=state.donors.find(x=>x.id===id),history=state.donations.filter(x=>x.donor===d.name);document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop"><div class="modal wide"><button class="modal-close">×</button><span class="eyebrow">Donor Medical Record</span><h2>${d.name} · ${d.id}</h2><dl class="detail-list"><div><dt>Blood Type</dt><dd>${d.type}</dd></div><div><dt>טלפון</dt><dd>${d.phone}</dd></div><div><dt>מצב רפואי</dt><dd>${d.conditions}</dd></div><div><dt>תרומה אחרונה</dt><dd>${d.lastDonation}</dd></div></dl><h3>היסטוריית תרומות</h3>${history.length?history.map(x=>`<div class="appointment"><strong>${x.id} · ${x.date}</strong><span>${x.status}</span></div>`).join(''):'<p>אין תרומות קודמות.</p>'}</div></div>`)}
function screeningForm(id){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop"><div class="modal"><button class="modal-close">×</button><h2>תוצאות Screening · ${id}</h2><form id="screeningForm" class="modal-form"><input type="hidden" name="screeningId" value="${id}">${['HIV','HBV','HCV','Syphilis'].map(t=>`<label>${t}<select name="${t.toLowerCase()}"><option>Negative</option><option>Positive</option></select></label>`).join('')}<button class="primary">אישור תוצאות ושחרור Blood Unit</button></form></div></div>`)}
function unit(id){let u=state.inventory.find(x=>x.id===id);document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop"><div class="modal"><button class="modal-close">×</button><span class="eyebrow">QR unit profile</span><h2>${u.id} · ${u.type}</h2><div class="qr">▦</div><dl class="detail-list"><div><dt>Component</dt><dd>${u.component}</dd></div><div><dt>Status</dt><dd>${u.status}</dd></div><div><dt>Expires</dt><dd>${u.expires}</dd></div><div><dt>Location</dt><dd>${u.branch} · Fridge A3</dd></div></dl><h3>Chain of custody</h3><div class="timeline"><p><b>Collected</b> · donor identity verified</p><p><b>Tested</b> · screening completed</p><p><b>Stored</b> · temperature within range</p></div></div></div>`)}
function matches(id){let q=state.requests.find(x=>x.id===id),m=rankUnits(state.inventory,{type:q.type,branch:q.hospital,today:'2026-09-20'});document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop"><div class="modal wide"><button class="modal-close">×</button><span class="eyebrow">Smart matching</span><h2>${id} · ${q.type}</h2><p>Ranked by compatibility, expiry, location, and rare-type protection.</p>${m.length?m.map((u,i)=>`<div class="match-row"><div><strong>#${i+1} ${u.id} · ${u.type}</strong><small>${u.branch} · expires in ${u.days} days</small></div><div><b>${u.score}</b><button class="primary" data-reserve="${u.id}" data-request="${id}">Reserve</button></div></div>`).join(''):'<div class="empty-state">No approved compatible unit is available.</div>'}</div></div>`)}
function route(){ensureExtendedState();let n=location.hash.slice(1)||'dashboard';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash===`#${n}`));view.innerHTML=(pages[n]||dashboard)();document.querySelector('.sidebar').classList.remove('open')}
document.addEventListener('submit',async e=>{e.preventDefault();let f=new FormData(e.target);if(e.target.id==='compatForm'){let d=f.get('donor'),r=f.get('recipient'),ok=isCompatible(d,r);document.querySelector('#compatResult').innerHTML=`<div class="result-icon ${ok?'ok':'no'}">${ok?'✓':'×'}</div><h3>${ok?'Compatible':'Not compatible'}</h3><p>${ok?`${d} appears in the compatible red-cell donor groups for ${r}.`:`${d} does not appear in the compatible red-cell donor groups for ${r}.`}</p><small>Compatible donors: ${compatibility[r].join(', ')}</small>`}if(e.target.id==='requestForm'){const item={patient:f.get('patient'),hospital:f.get('hospital'),type:f.get('type'),units:+f.get('units'),urgency:f.get('urgency')};if(!await persist('/api/requests',item)){state.requests.unshift({id:`REQ-${1045+state.requests.length}`,...item,status:'Open'});state.audit.unshift({time:'Now',user:'Noa Adler',action:'Created request',record:state.requests[0].id});save()}document.querySelector('.modal-backdrop').remove();notify('הבקשה נשמרה ונרשמה ב־Audit Trail');route()}if(e.target.id==='donationForm'){let eligibility=donorEligibility({age:+f.get('age'),weight:+f.get('weight'),daysSinceDonation:+f.get('days')});if(!eligibility.eligible)return notify(eligibility.reason);const item={donor:f.get('donor'),phone:f.get('phone'),type:f.get('type'),conditions:f.get('conditions')||'None reported'};if(!await persist('/api/donations',item)){const donationId=`DON-${3111+state.donations.length}`,unitId=`LF-${2048+state.inventory.length}`,screeningId=`SCR-${5001+state.screenings.length}`;state.donations.unshift({id:donationId,...item,date:new Date().toISOString().slice(0,10),status:'Testing'});state.donors.unshift({id:`DNR-${1001+state.donors.length}`,name:item.donor,phone:item.phone,type:item.type,conditions:item.conditions,lastDonation:new Date().toISOString().slice(0,10)});state.inventory.push({id:unitId,type:item.type,component:'Red cells',branch:'Soroka',expires:'2026-11-01',status:'Pending Testing'});state.screenings.unshift({id:screeningId,donationId,unitId,hiv:'Pending',hbv:'Pending',hcv:'Pending',syphilis:'Pending',result:'Pending',testedAt:''});save()}document.querySelector('.modal-backdrop').remove();notify('התרומה נקלטה ונוצרה Blood Unit ב־Pending Testing');location.hash='screening';route()}if(e.target.id==='screeningForm'){const id=f.get('screeningId'),item={screening_id:id,hiv:f.get('hiv'),hbv:f.get('hbv'),hcv:f.get('hcv'),syphilis:f.get('syphilis')};if(!await persist('/api/screenings',item)){const s=state.screenings.find(x=>x.id===id),clean=['hiv','hbv','hcv','syphilis'].every(k=>item[k]==='Negative');Object.assign(s,{...item,result:clean?'Clean':'Rejected',testedAt:new Date().toLocaleString()});state.inventory.find(x=>x.id===s.unitId).status=clean?'Available':'Rejected';state.donations.find(x=>x.id===s.donationId).status=clean?'Approved':'Rejected';save()}document.querySelector('.modal-backdrop').remove();notify('תוצאות הבדיקות נשמרו וסטטוס Blood Unit עודכן');route()}if(e.target.id==='labForm'){const item={patient:f.get('patient'),patientCode:f.get('patientCode'),symptoms:f.get('symptoms'),testType:f.get('testType'),doctor:f.get('doctor')};if(!await persist('/api/lab-orders',item)){state.labOrders.unshift({id:`LAB-${7001+state.labOrders.length}`,...item,status:'Ordered'});save()}document.querySelector('.modal-backdrop').remove();notify('הזמנת הבדיקה נשלחה למעבדה');route()}});
const filterInventory=()=>{const search=(document.querySelector('#inventorySearch')?.value||'').trim().toLowerCase(),status=document.querySelector('#statusFilter')?.value||'All statuses',rows=[...document.querySelectorAll('.inventory-row')];let visible=0;rows.forEach(row=>{const show=(!search||row.dataset.search.includes(search))&&(status==='All statuses'||row.dataset.status===status);row.hidden=!show;if(show)visible++});const count=document.querySelector('#inventoryCount'),empty=document.querySelector('#inventoryEmpty');if(count)count.textContent=`${visible} Blood Units`;if(empty)empty.hidden=visible!==0};
function donationStep(step){document.querySelectorAll('[data-donation-step]').forEach(x=>x.classList.toggle('active',x.dataset.donationStep===step));const info=document.querySelector('#donationStepInfo'),rows=[...document.querySelectorAll('.donation-row')];rows.forEach(row=>row.hidden=false);if(step==='donor'){location.hash='donors';return}if(step==='eligibility'){modal('donation');return}if(step==='testing'){location.hash='screening';return}if(step==='collection'){rows.forEach(row=>row.hidden=row.dataset.status!=='Testing');info.innerHTML='<b>איסוף Blood Unit</b><span>מוצגות תרומות שנאספו וממתינות לבדיקות המעבדה.</span>'}if(step==='approval'){rows.forEach(row=>row.hidden=row.dataset.status!=='Approved');info.innerHTML='<b>אישור למלאי</b><span>מוצגות תרומות שעברו Screening מלא ואושרו לשימוש.</span>'}}
document.addEventListener('input',e=>{if(e.target.matches('#inventorySearch,#statusFilter'))filterInventory()});document.addEventListener('change',e=>{if(e.target.matches('#statusFilter'))filterInventory()});
document.addEventListener('click',async e=>{let r=e.target.closest('[data-route]');if(r)location.hash=r.dataset.route;let m=e.target.closest('[data-modal]');if(m)modal(m.dataset.modal);if(e.target.closest('.modal-close')||e.target.classList.contains('modal-backdrop'))e.target.closest('.modal-backdrop')?.remove();let u=e.target.closest('[data-unit]');if(u)unit(u.dataset.unit);let donor=e.target.closest('[data-donor]');if(donor)donorFile(donor.dataset.donor);let screen=e.target.closest('[data-screen]');if(screen)screeningForm(screen.dataset.screen);let mt=e.target.closest('[data-match]');if(mt)matches(mt.dataset.match);let rs=e.target.closest('[data-reserve]');if(rs){let u=state.inventory.find(x=>x.id===rs.dataset.reserve),q=state.requests.find(x=>x.id===rs.dataset.request);if(u.status!=='Available')return notify('Safety check blocked this allocation');if(!await persist('/api/reservations',{unit_id:u.id,request_id:q.id})){u.status='Reserved';q.status='Matched';state.audit.unshift({time:'Now',user:'Noa Adler',action:'Reserved compatible unit',record:u.id});save()}e.target.closest('.modal-backdrop').remove();notify(`${u.id} reserved for ${q.id}`);route()}let tab=e.target.closest('[data-admin-tab]');if(tab){document.querySelectorAll('[data-admin-tab]').forEach(x=>x.classList.toggle('active',x===tab));const p=document.querySelector('#adminPanel');p.innerHTML=JSON.parse(p.dataset.panels)[tab.dataset.adminTab]}let a=e.target.closest('[data-action]')?.dataset.action;if(a==='export'){let b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),x=document.createElement('a');x.href=URL.createObjectURL(b);x.download='lifeflow-export.json';x.click();URL.revokeObjectURL(x.href);notify('Export prepared')}if(a==='scan')notify('QR scanner active — choose Details to inspect a Blood Unit');if(a==='campaign')notify('O- campaign draft created');if(a==='emergency'){e.target.textContent=e.target.textContent.includes('Activate')?'Emergency mode active':'Activate emergency mode';notify('Emergency state recorded')}});
document.addEventListener('click',e=>{const step=e.target.closest('[data-donation-step]');if(step)donationStep(step.dataset.donationStep)});
const roleProfiles={staff:['נועה אדלר','צוות Blood Bank','dashboard'],donor:['דנה לוי','Blood Donor','donations'],hospital:['ד״ר סמיר חדאד','צוות בית חולים','requests'],admin:['נועה אדלר','מנהל מערכת','admin']};
function enter(role,preserveRoute=false){const p=roleProfiles[role]||roleProfiles.staff;sessionStorage.setItem('lifeflow-role',role);document.querySelector('#profileName').textContent=p[0];document.querySelector('#profileRole').textContent=p[1];document.querySelector('#loginGate').classList.add('hidden');if(!preserveRoute||!location.hash)location.hash=p[2]}
document.querySelectorAll('[data-login]').forEach(b=>b.addEventListener('click',()=>enter(b.dataset.login)));document.querySelector('#logoutBtn').addEventListener('click',()=>{sessionStorage.removeItem('lifeflow-role');document.querySelector('#loginGate').classList.remove('hidden')});document.querySelector('#menuBtn').addEventListener('click',()=>document.querySelector('.sidebar').classList.toggle('open'));addEventListener('hashchange',route);const savedRole=sessionStorage.getItem('lifeflow-role');if(savedRole)enter(savedRole,true);route();localize();api('/api/state').then(remote=>{state=remote;save();route()}).catch(()=>{});
